import React, { useEffect, useMemo, useRef, useState } from "react";
import {
  Alert, Accordion, AccordionDetails, AccordionSummary, Avatar, Box, Button, Chip,
  CircularProgress, Dialog, DialogActions, DialogContent, DialogTitle, Divider,
  FormControl, IconButton, InputLabel, List, ListItemButton, ListItemIcon, ListItemText,
  MenuItem, Paper, Select, Skeleton, Stack, TextField, Toolbar, Tooltip,
  Typography
} from "@mui/material";
import {
  ArrowBack, ArrowForward, AutoAwesome, ChevronRight, DeleteOutlineOutlined,
  Description, Download, ExpandMore, FactCheck, FolderOpen, Lock,
  PlayArrow, Send, Source, Stop, UploadFile, Visibility
} from "@mui/icons-material";
import { createTheme, ThemeProvider, alpha } from "@mui/material/styles";
import { Group, Panel, Separator, useDefaultLayout } from "react-resizable-panels";
import { SimpleTreeView, TreeItem } from "@mui/x-tree-view";
import { ChatComposer, ChatComposerTextArea, ChatComposerToolbar } from "@mui/x-chat";
import { ChatProvider } from "@mui/x-chat/headless";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import { hatchMuiThemeOptions } from "@hatch/ui";
import { dashboardRequest } from "./data.js";
import { chatEntries, groupToolEntries } from "./factoryMessages.js";
import { subscribeFactoryEvents } from "./factoryEvents.js";
import { FactoryVoicePlayer } from "./factoryVoicePlayer.js";
import { createFactoryAgentTranslator } from "./factoryAgentsI18n.js";
import { agentDependencyGaps, agentStateKey, localizeAgentText } from "./factoryAgentState.js";
import { creatorFactoryPath, FACTORY_SECTION_AGENTS, factorySectionForAgent } from "./creatorRoutes.js";
import "./factoryAgents.css";

const STAGES = [
  ["sources", "sourcesStage", "sourcesStageDescription", FACTORY_SECTION_AGENTS.sources, Source],
  ["build", "generationStage", "generationStageDescription", FACTORY_SECTION_AGENTS.build, AutoAwesome],
  ["evaluate", "evaluationStage", "evaluationStageDescription", FACTORY_SECTION_AGENTS.evaluate, FactCheck]
];
const api = (route, options = {}) => dashboardRequest(route, { ...options, body: options.body === undefined ? undefined : JSON.stringify(options.body) });
const factoryRoot = productId => `/v1/creator/products/${encodeURIComponent(productId)}/factory-agents`;
const endpoint = (root, id, action = "") => `${root}/sessions/${id}${action ? `/${action}` : ""}`;

const theme = createTheme({ ...hatchMuiThemeOptions, components: { ...hatchMuiThemeOptions.components, MuiTextField: { defaultProps: { size: "small" } } } });

function Markdown({ children, filePath = "output/chat.md", files = [], onOpenFile, t }) {
  const link = ({ href, ...props }) => {
    let local;
    if (href && !/^(?:[a-z][\w+.-]*:|\/\/|#)/i.test(href)) {
      try { const relative = /^(input|output)\//.test(href) ? `/${href}` : href; const path = decodeURIComponent(new URL(relative, `https://workspace.invalid/${filePath}`).pathname.slice(1)); local = files.find(file => file.path === path)?.path; } catch { /* keep unsupported links normal */ }
    }
    return local && onOpenFile ? <a {...props} href={href} onClick={event => { event.preventDefault(); onOpenFile(local); }} /> : <a {...props} href={href} target="_blank" rel="noreferrer" />;
  };
  return <div className="factory-markdown"><ReactMarkdown remarkPlugins={[remarkGfm]} components={{ a: link, img: ({ alt }) => <Typography component="span" color="text.secondary">{t("imageAlt", alt || t("externalImage"))}</Typography> }}>{children || ""}</ReactMarkdown></div>;
}

function ErrorNotice({ error }) { return error ? <Alert severity="error" variant="outlined" sx={{ m: 1.5 }}>{error}</Alert> : null; }

export function FactoryAgents({ productId, section, agent, navigate, locale = "en" }) {
  const t = useMemo(() => createFactoryAgentTranslator(locale), [locale]);
  const [sessions, setSessions] = useState([]); const [agents, setAgents] = useState([]); const [config, setConfig] = useState(null); const [productName, setProductName] = useState(""); const [error, setError] = useState(""); const importPicker = useRef(null);
  const root = useMemo(() => factoryRoot(productId), [productId]);
  const stage = section ?? null;
  const selected = agent ?? null;
  const goToFactory = (nextStage, nextAgent) => navigate(creatorFactoryPath(productId, nextStage, nextAgent));
  const applyNavigation = value => { setSessions(value.sessions || []); setAgents(value.agents || []); };
  const refresh = () => api(`${root}/sessions`).then(applyNavigation).catch(e => setError(e.message));
  const refreshConfig = () => api(`${root}/config`).then(value => { setConfig(value); if (value.agents) setAgents(value.agents); }).catch(e => setError(e.message));
  const refreshProduct = () => api(`/v1/creator/products/${encodeURIComponent(productId)}`).then(value => setProductName(value.product?.name ?? value.name ?? "")).catch(e => setError(e.message));
  useEffect(() => { refresh(); refreshConfig(); refreshProduct(); return subscribeFactoryEvents({ url: `${root}/events`, onMessage: event => { const value = JSON.parse(event.data); if (["state", "todos", "files"].includes(value.type)) refresh(); }, onError: () => setError(t("workspaceConnectionLost")), onOpen: () => { setError(""); refresh(); refreshConfig(); refreshProduct(); } }); }, [productId, root, t]);
  const agentEntry = role => agents.find(item => item.role === role);
  const agentName = role => localizeAgentText(agentEntry(role)?.name, locale);
  const agentSession = role => sessions.filter(item => item.role === role).sort((a, b) => b.updatedAt.localeCompare(a.updatedAt))[0];
  const openAgent = async role => { try { const targetStage = factorySectionForAgent(role); if (!targetStage) throw new Error(t("agentStateUnavailable")); const entry = agentEntry(role); if (!entry) throw new Error(t("agentStateUnavailable")); if (entry.state === "locked") { goToFactory(targetStage, role); return; } let session = agentSession(role); if (!session) session = await api(`${root}/sessions`, { method: "POST", body: { role } }); await refresh(); goToFactory(targetStage, role); } catch (e) { setError(factoryError(e, t, agentName)); } };
  const uploadProjectFiles = async files => { try { let transport = sessions.find(item => item.role === "research"); if (!transport) transport = await api(`${root}/sessions`, { method: "POST", body: { role: "research" } }); for (const file of files) { if (file.size > 20 * 1024 * 1024) throw new Error(t("fileTooLarge", file.name)); const bytes = new Uint8Array(await file.arrayBuffer()); let binary = ""; for (let i = 0; i < bytes.length; i += 8192) binary += String.fromCharCode(...bytes.subarray(i, i + 8192)); await api(endpoint(root, transport.id, "files"), { method: "POST", body: { path: `input/manual/${file.name}`, base64: btoa(binary), mimeType: file.type || undefined } }); } await refresh(); } catch (e) { setError(factoryError(e, t, agentName)); } };
  const stageSummary = roles => { const entries = roles.map(agentEntry).filter(Boolean); const running = entries.filter(item => item.state === "running").length; const updates = entries.filter(item => item.state === "update_available").length; const completed = entries.filter(item => item.state === "complete").length; if (running) return t("stageRunning", running); if (updates) return t("stageHasUpdates", updates); if (completed) return t("stageComplete", completed); return entries.some(item => item.state === "ready") ? t("stageReady") : t("stageWaiting"); };
  const selectedEntry = selected ? agentEntry(selected) : null; const selectedSession = selected ? agentSession(selected) : null;
  return <ThemeProvider theme={theme}><Box className="factory-app" aria-label={t("factory")}><FactoryHeader productName={productName} stage={stage} selected={selected} agentName={agentName} t={t} navigate={navigate} /><Box className="factory-body" sx={{ display: "flex", flex: 1, minHeight: 0 }}><FactorySidebar stage={stage} selected={selected} agents={agents} agentName={agentName} stageSummary={stageSummary} goToFactory={goToFactory} locale={locale} t={t} /><Box className="factory-content" sx={{ flex: 1, minWidth: 0, minHeight: 0, position: "relative" }}><ErrorNotice error={error} />{selected ? selectedSession ? <Workspace key={selectedSession.id} root={root} id={selectedSession.id} entry={selectedEntry} agents={agents} sessions={sessions} config={config} onChanged={refresh} onOpenAgent={openAgent} agentName={agentName} locale={locale} t={t} /> : <AgentStartWorkspace entry={selectedEntry} onOpenAgent={openAgent} agentName={agentName} t={t} /> : stage ? <StageOverview stage={stage} agents={agents} sessions={sessions} agentName={agentName} onOpenAgent={openAgent} importPicker={importPicker} uploadProjectFiles={uploadProjectFiles} locale={locale} t={t} /> : <FactoryOverview stages={STAGES} stageSummary={stageSummary} goToFactory={goToFactory} t={t} />}</Box></Box></Box></ThemeProvider>;
}

function FactoryHeader({ productName, stage, selected, agentName, t, navigate }) {
  const title = selected ? agentName(selected) : stage ? t(STAGES.find(item => item[0] === stage)?.[1]) : t("factory");
  return <Box component="header" className="factory-header" sx={{ height: 56, flexShrink: 0, display: "flex", alignItems: "center", px: 1.5, gap: 1.5, borderBottom: 1, borderColor: "divider", bgcolor: "background.paper" }}><Tooltip title={t("product")}><IconButton size="small" onClick={() => navigate("/studio/products")}><ArrowBack fontSize="small" /></IconButton></Tooltip><Divider orientation="vertical" flexItem sx={{ my: 1.25 }} /><Box sx={{ minWidth: 0 }}><Typography variant="caption" color="text.secondary" sx={{ display: "block", lineHeight: 1.1 }}>{productName || t("product")}</Typography><Typography variant="subtitle1" noWrap sx={{ fontWeight: 700 }}>{title}</Typography></Box><Box sx={{ flex: 1 }} /></Box>;
}

function FactorySidebar({ stage, selected, agents, agentName, stageSummary, goToFactory, locale, t }) {
  const selectedItem = selected || stage || null;
  const handleSelection = (_, itemId) => { const id = String(itemId); const parent = STAGES.find(item => item[3].includes(id)); if (parent) goToFactory(parent[0], id); else if (STAGES.some(item => item[0] === id)) goToFactory(id); };
  return <Box component="aside" className="factory-stage-rail" sx={{ width: 248, flexShrink: 0, borderRight: 1, borderColor: "divider", bgcolor: "var(--hatch-ui-surface-sidebar)", overflow: "auto", py: 1.5 }}><SimpleTreeView aria-label={t("factory")} selectedItems={selectedItem} defaultExpandedItems={stage ? [stage] : STAGES.map(item => item[0])} expansionTrigger="iconContainer" onSelectedItemsChange={handleSelection} sx={{ px: 1 }}>
    {STAGES.map(([id, title, description, roles, Icon]) => <TreeItem key={id} itemId={id} label={<Stack direction="row" spacing={1} alignItems="center" sx={{ py: .5 }}><Icon fontSize="small" /><Box sx={{ minWidth: 0, flex: 1 }}><Typography variant="body2" fontWeight={650} noWrap>{t(title)}</Typography><Typography variant="caption" color="text.secondary" noWrap>{stageSummary(roles)}</Typography></Box></Stack>}>{roles.map(role => { const entry = agents.find(item => item.role === role); if (!entry) return null; return <TreeItem key={role} itemId={role} label={<Stack direction="row" spacing={1} alignItems="center" sx={{ py: .35 }}><Typography variant="caption" noWrap sx={{ flex: 1 }}>{localizeAgentText(entry.name, locale)}</Typography><AgentState entry={entry} agentName={agentName} t={t} compact /></Stack>} />; })}</TreeItem>)}
  </SimpleTreeView></Box>;
}

function FactoryOverview({ stages, stageSummary, goToFactory, t }) {
  return <Box className="factory-overview" sx={{ height: "100%", overflow: "auto", p: { xs: 3, md: 5 }, maxWidth: 980 }}><Typography variant="h4" sx={{ mt: 1, mb: 1 }}>{t("factoryPromise")}</Typography><Typography color="text.secondary" sx={{ maxWidth: 600, mb: 4 }}>{t("factoryPromiseDescription")}</Typography><Paper variant="outlined" sx={{ overflow: "hidden" }}><List disablePadding>{stages.map(([id, title, description, roles, Icon], index) => <React.Fragment key={id}><ListItemButton onClick={() => goToFactory(id)} sx={{ px: 2.5, py: 2 }}><ListItemIcon><Avatar sx={{ width: 36, height: 36, bgcolor: alpha(theme.palette.primary.main, .1), color: "primary.main" }}><Icon fontSize="small" /></Avatar></ListItemIcon><ListItemText primary={<Typography fontWeight={700}>{`0${index + 1}  ${t(title)}`}</Typography>} secondary={<>{t(description)}<br /><Typography component="span" variant="caption" color="text.secondary">{stageSummary(roles)}</Typography></>} /><ArrowForward color="action" fontSize="small" /></ListItemButton>{index < stages.length - 1 && <Divider />}</React.Fragment>)}</List></Paper></Box>;
}

function StageOverview({ stage, agents, sessions, agentName, onOpenAgent, importPicker, uploadProjectFiles, locale, t }) {
  const data = STAGES.find(item => item[0] === stage); const entries = (data?.[3] || []).map(role => agents.find(item => item.role === role)).filter(Boolean).sort((a, b) => a.order - b.order); const researchSession = sessions.filter(item => item.role === "research").sort((a, b) => b.updatedAt.localeCompare(a.updatedAt))[0]; const manualFiles = researchSession?.files?.filter(record => record.path.startsWith("input/manual/")) || [];
  return <Box className="factory-stage-overview" sx={{ height: "100%", overflow: "auto", p: { xs: 3, md: 5 } }}><Typography variant="h4">{t(data?.[1])}</Typography><Typography color="text.secondary" sx={{ mt: 1, mb: 3, maxWidth: 680 }}>{t(data?.[2])}</Typography>{stage === "sources" && <Paper variant="outlined" sx={{ mb: 2 }}><ListItemButton onClick={() => importPicker.current?.click()} sx={{ px: 2.5, py: 2 }}><ListItemIcon><UploadFile color="primary" /></ListItemIcon><ListItemText primary={t("uploadSources")} secondary={t("uploadSourcesBody")} /><Button variant="contained" size="small">{t("chooseFiles")}</Button></ListItemButton><input ref={importPicker} hidden type="file" multiple aria-label={t("uploadInputFiles")} onChange={event => { uploadProjectFiles([...event.target.files]); event.target.value = ""; }} /></Paper>}{stage === "sources" && manualFiles.length > 0 && <Paper variant="outlined" sx={{ mb: 2, overflow: "hidden" }}><Box sx={{ px: 2.5, py: 1.5, display: "flex", alignItems: "center", gap: 1, borderBottom: 1, borderColor: "divider" }}><FolderOpen fontSize="small" /><Typography variant="subtitle2" fontWeight={750}>{t("manualUploads")}</Typography><Chip size="small" label={t("fileCount", manualFiles.length)} sx={{ ml: "auto" }} /></Box><List dense disablePadding>{manualFiles.map(record => <ListItemButton key={record.path} onClick={() => onOpenAgent("research")}><ListItemIcon><Description fontSize="small" /></ListItemIcon><ListItemText primary={record.path.replace("input/manual/", "")} secondary={record.mimeType || t("files")} primaryTypographyProps={{ noWrap: true }} /><ChevronRight fontSize="small" color="disabled" /></ListItemButton>)}</List></Paper>}<Paper variant="outlined" sx={{ overflow: "hidden" }}><List disablePadding>{entries.map((entry, index) => <React.Fragment key={entry.role}><AgentRow entry={entry} session={sessions.filter(item => item.role === entry.role).sort((a, b) => b.updatedAt.localeCompare(a.updatedAt))[0]} agentName={agentName} locale={locale} onClick={() => onOpenAgent(entry.role)} t={t} />{index < entries.length - 1 && <Divider />}</React.Fragment>)}</List></Paper></Box>;
}

function AgentRow({ entry, session, agentName, locale, onClick, t }) { const completed = session?.todos?.filter(todo => todo.status === "completed").length || 0; return <ListItemButton onClick={onClick} sx={{ px: 2.5, py: 2 }}><ListItemIcon><Avatar sx={{ width: 36, height: 36, bgcolor: entry.state === "locked" ? "action.disabledBackground" : "primary.main" }}>{entry.state === "locked" ? <Lock fontSize="small" /> : <AutoAwesome fontSize="small" />}</Avatar></ListItemIcon><ListItemText primary={localizeAgentText(entry.name, locale)} secondary={<>{localizeAgentText(entry.hint, locale)} {session?.todos?.length ? `· ${completed}/${session.todos.length}` : ""}</>} primaryTypographyProps={{ fontWeight: 700 }} secondaryTypographyProps={{ fontSize: 12 }} /><AgentState entry={entry} agentName={agentName} t={t} /><ChevronRight fontSize="small" color="disabled" /></ListItemButton>; }

function Workspace({ root, id, entry, agents, sessions, config, onChanged, onOpenAgent, agentName, locale, t }) {
  const layoutStorage = typeof window !== "undefined" ? window.localStorage : undefined; const { defaultLayout, onLayoutChanged } = useDefaultLayout({ id: `factory-workspace-${id}`, storage: layoutStorage, onlySaveAfterUserInteractions: true });
  const [session, setSession] = useState(null); const [error, setError] = useState(""); const [draft, setDraft] = useState(() => sessionStorage.getItem(`factory-draft:${id}`) || ""); const [stream, setStream] = useState(""); const [activity, setActivity] = useState(""); const [activityVisible, setActivityVisible] = useState(true); const [file, setFile] = useState(null); const [prompt, setPrompt] = useState(null); const [busy, setBusy] = useState(false); const [speaking, setSpeaking] = useState(null); const [selectedOutputs, setSelectedOutputs] = useState([]); const [destinationRole, setDestinationRole] = useState(""); const [handoffNotice, setHandoffNotice] = useState("");
  const composer = useRef(null); const chat = useRef(null); const stick = useRef(true); const voiceHandler = useRef(() => {}); const refresh = () => api(endpoint(root, id)).then(setSession);
  useEffect(() => { let live = true; const load = (clearStream = false) => api(endpoint(root, id)).then(value => { if (live) { setSession(value); setError(""); if (clearStream) { setStream(""); setActivityVisible(false); } } }).catch(e => { if (live) setError(e.message); }); load(); const unsubscribe = subscribeFactoryEvents({ url: `${root}/events`, onMessage: event => { const value = JSON.parse(event.data); if (value.sessionId !== id) return; if (value.type.startsWith("voice.")) voiceHandler.current(value); if (value.type === "delta") { setActivityVisible(false); setStream(previous => previous + value.text); } if (value.type === "message") load(true); if (value.type === "state") load(); if (value.type === "tool") { setActivityVisible(true); setActivity(t("callingTool", t(toolActionKey(value.name)))); } if (value.type === "thinking") { setActivityVisible(true); setActivity(t("thinking")); } if (value.type === "compacting") { setActivityVisible(true); setActivity(t("compacting")); } if (value.type === "tool_end") { setActivityVisible(true); setActivity(value.isError ? t("toolErrorContinuing") : t("continuing")); } if (["files", "todos"].includes(value.type)) load(); }, onError: () => { if (live) setActivity(t("reconnecting")); }, onOpen: () => { if (live) { setActivity(""); load(); } } }); return () => { live = false; unsubscribe(); }; }, [root, id, t]);
  useEffect(() => { sessionStorage.setItem(`factory-draft:${id}`, draft); }, [id, draft]); useEffect(() => { setSelectedOutputs(paths => paths.filter(path => session?.files.some(record => record.path === path && path.startsWith("output/")))); }, [session?.files]); useEffect(() => { if (stick.current && chat.current) chat.current.scrollTop = chat.current.scrollHeight; }, [stream, session?.messages.length]);
  const perform = async fn => { setError(""); setBusy(true); try { await fn(); await refresh(); onChanged(); } catch (e) { setError(factoryError(e, t, agentName)); } finally { setBusy(false); } };
  const composerAdapter = useMemo(() => ({
    sendMessage: async ({ message, signal }) => {
      const content = (message.parts || []).filter(part => part.type === "text").map(part => part.text).join("\n").trim();
      if (!content) return new ReadableStream({ start(controller) { controller.close(); } });
      setError(""); setActivityVisible(true); setActivity(t("thinking"));
      try {
        await api(endpoint(root, id, "message"), { method: "POST", body: { content }, signal });
        onChanged();
        return new ReadableStream({ start(controller) { controller.close(); } });
      } catch (e) {
        setError(factoryError(e, t, agentName));
        throw e;
      }
    },
    stop: () => { void perform(() => api(endpoint(root, id, "stop"), { method: "POST", body: {} })); }
  }), [root, id, t, agentName, onChanged]);
  if (!session) return <Stack sx={{ p: 4 }} spacing={1}><Skeleton width="35%" /><Skeleton width="80%" /><Skeleton width="70%" /><ErrorNotice error={error} /></Stack>;
  const running = session.status === "running"; const locked = entry?.state === "locked"; const destinations = agents.filter(candidate => candidate.role !== session.role && candidate.state !== "locked").filter(candidate => sessions.find(item => item.role === candidate.role)?.status !== "running").sort((a, b) => a.order - b.order);
  const upload = files => perform(async () => { for (const f of files) { if (f.size > 20 * 1024 * 1024) throw new Error(t("fileTooLarge", f.name)); const bytes = new Uint8Array(await f.arrayBuffer()); let binary = ""; for (let i = 0; i < bytes.length; i += 8192) binary += String.fromCharCode(...bytes.subarray(i, i + 8192)); await api(endpoint(root, id, "files"), { method: "POST", body: { path: `input/manual/${f.name}`, base64: btoa(binary), mimeType: f.type || undefined } }); } });
  const openFile = path => setFile(path); const addToChat = (path, quote) => { const reference = `${t("fileReference", path)}${quote ? `\n\n${quote.split("\n").map(line => `> ${line}`).join("\n")}` : ""}`; setDraft(previous => `${previous}${previous.trim() ? "\n\n" : ""}${reference}\n\n`); requestAnimationFrame(() => composer.current?.focus()); }; const useLatest = () => { setActivityVisible(true); return perform(async () => { await api(endpoint(root, id, "message"), { method: "POST", body: { content: t("useLatestMessage") } }); setActivity(t("thinking")); }); }; const transferOutputs = () => perform(async () => { const destination = destinations.find(candidate => candidate.role === destinationRole); if (!destination || !selectedOutputs.length) return; let target = sessions.filter(item => item.role === destinationRole).sort((a, b) => b.updatedAt.localeCompare(a.updatedAt))[0]; if (!target) target = await api(`${root}/sessions`, { method: "POST", body: { role: destinationRole } }); await api(endpoint(root, target.id, "transfer"), { method: "POST", body: { fromSessionId: id, files: selectedOutputs.map(path => ({ path })) } }); setHandoffNotice(t("filesSent", selectedOutputs.length, agentName(destinationRole))); setSelectedOutputs([]); });
  return <Group className="factory-workspace" id="factory-workspace" orientation="horizontal" defaultLayout={defaultLayout} onLayoutChanged={onLayoutChanged} style={{ height: "100%", minHeight: 0 }}><Panel className="factory-workspace-pane" id="factory-main" defaultSize="72%" minSize="58%"><ChatPanel session={session} entry={entry} root={root} id={id} config={config} busy={busy} draft={draft} setDraft={setDraft} stream={stream} activity={activity} activityVisible={activityVisible} composer={composer} composerAdapter={composerAdapter} chat={chat} stick={stick} running={running} locked={locked} error={error} setError={setError} perform={perform} onOpenFile={openFile} agentName={agentName} voiceHandler={voiceHandler} speaking={speaking} setSpeaking={setSpeaking} t={t} prompt={prompt} setPrompt={setPrompt} /></Panel><Separator className="factory-resize-handle" /><Panel className="factory-workspace-pane" id="factory-inspector" defaultSize="28%" minSize="24%" collapsible collapsedSize="0%"><InspectorPanel entry={entry} session={session} root={root} id={id} running={running} busy={busy} file={file} setFile={setFile} upload={upload} selectedOutputs={selectedOutputs} setSelectedOutputs={setSelectedOutputs} destinations={destinations} destinationRole={destinationRole} setDestinationRole={setDestinationRole} transferOutputs={transferOutputs} handoffNotice={handoffNotice} addToChat={addToChat} agentName={agentName} onOpenAgent={onOpenAgent} useLatest={useLatest} t={t} locale={locale} perform={perform} /></Panel></Group>;
}

function ChatPanel({ session, entry, root, id, config, busy, draft, setDraft, stream, activity, activityVisible, composer, composerAdapter, chat, stick, running, locked, error, setError, perform, onOpenFile, agentName, voiceHandler, speaking, setSpeaking, t, prompt, setPrompt }) {
  const composerDisabled = locked || busy || !config?.services.model;
  const sendDisabled = composerDisabled || !(draft || "").trim();
  const stopResponse = () => perform(() => api(endpoint(root, id, "stop"), { method: "POST", body: {} }));
  const composerSx = { border: "1px solid var(--hatch-ui-border-soft)", borderRadius: "var(--hatch-radius-dialog)", backgroundColor: "var(--hatch-ui-surface-solid)", px: 1.5, py: 1, "&:focus-within": { borderColor: "var(--hatch-ui-border-soft)", boxShadow: "none" }, "&:focus-within:not([data-disabled])": { borderColor: "var(--hatch-ui-border-soft)", boxShadow: "none" }, "& textarea:focus": { outline: "none", boxShadow: "none" } };
  return <Box className="factory-chat-panel" sx={{ height: "100%", minWidth: 0, minHeight: 0, display: "flex", flexDirection: "column", bgcolor: "background.paper" }}>
    <Toolbar className="factory-pane-header" variant="dense" sx={{ minHeight: 56, px: 2, borderBottom: 1, borderColor: "divider" }}>
      <Box sx={{ minWidth: 0, flex: 1 }}><Typography variant="subtitle1" fontWeight={750} noWrap>{agentName(session.role)}</Typography></Box>
      <Tooltip title={t("viewPrompt")}><IconButton size="small" onClick={async () => { try { setPrompt((await api(endpoint(root, id, "prompt"))).content); } catch (e) { setError(e.message); } }}><Visibility fontSize="small" /></IconButton></Tooltip>
    </Toolbar>
    <Box className="factory-chat-scroll" ref={chat} sx={{ flex: 1, minHeight: 0, overflow: "auto", overscrollBehavior: "contain", px: 2.5, py: 2 }} onScroll={event => { const target = event.currentTarget; stick.current = target.scrollHeight - target.scrollTop - target.clientHeight < 80; }}>
      {!session.messages.length && <Box sx={{ py: 8, textAlign: "center" }}><AutoAwesome color="primary" sx={{ fontSize: 32, mb: 1 }} /><Typography variant="h6" fontWeight={750}>{t("startChatHeading")}</Typography><Typography variant="body2" color="text.secondary">{t("messagePlaceholder")}</Typography></Box>}
      {groupToolEntries(chatEntries(session.messages)).map(item => item.type === "toolGroup" ? <ToolGroup key={item.key} items={item.items} running={running && item.isCurrentTurn} t={t} /> : item.type === "tool" ? <ToolMessage key={item.key} call={item.call} result={item.result} running={running && item.isCurrentTurn} t={t} /> : <Message key={item.key} message={item.message} files={session.files} onOpenFile={onOpenFile} speaking={speaking} t={t} />)}
      {stream && <Message message={{ role: "assistant", content: stream }} files={session.files} onOpenFile={onOpenFile} speaking={speaking} t={t} />}
      {running && activityVisible && <Stack direction="row" spacing={1} alignItems="center" sx={{ py: 1 }}><CircularProgress size={14} /><Typography variant="caption" color="primary.main">{activity || (session.activeTool ? t("callingTool", t(toolActionKey(session.activeTool))) : t("working"))}</Typography></Stack>}
    </Box>
    <ErrorNotice error={error || session.error} />
    {session.role === "voice" && <VoiceControls root={root} id={id} enabled={!locked && config?.services.voice} handler={voiceHandler} onSpeaking={setSpeaking} onError={setError} t={t} />}
    <Box className="factory-chat-composer" sx={{ p: 1.5, borderTop: 1, borderColor: "divider" }}>
      <ChatProvider adapter={composerAdapter} composerValue={draft} onComposerValueChange={setDraft}>
        <ChatComposer disabled={composerDisabled} features={{ attachments: false }} sx={composerSx}>
          <ChatComposerTextArea ref={composer} maxRows={7} disabled={running} aria-label={t("messageLabel")} placeholder={t(locked ? "completeDependenciesToStart" : "messagePlaceholder")} />
          <ChatComposerToolbar sx={{ minHeight: 30, pt: 0.5 }}>
            {running ? <IconButton type="button" aria-label={t("stop")} onClick={stopResponse} disabled={busy} size="small" sx={{ ml: "auto", width: 36, height: 36, borderRadius: "50%", bgcolor: "error.main", color: "error.contrastText", "&:hover": { bgcolor: "error.dark" } }}><Stop fontSize="small" /></IconButton> : <IconButton type="submit" aria-label={t("send")} disabled={sendDisabled} size="small" sx={{ ml: "auto", width: 36, height: 36, borderRadius: "50%", bgcolor: "primary.main", color: "primary.contrastText", "&:hover": { bgcolor: "primary.dark" }, "&.Mui-disabled": { bgcolor: "action.disabledBackground", color: "action.disabled" } }}><Send fontSize="small" /></IconButton>}
          </ChatComposerToolbar>
        </ChatComposer>
      </ChatProvider>
    </Box>
    <PromptDialog prompt={prompt} onClose={() => setPrompt(null)} t={t} />
  </Box>;
}

function InspectorPanel({ entry, session, root, id, running, busy, file, setFile, upload, selectedOutputs, setSelectedOutputs, destinations, destinationRole, setDestinationRole, transferOutputs, handoffNotice, addToChat, agentName, onOpenAgent, useLatest, t, locale, perform }) {
  const inputFiles = session.files.filter(record => record.path.startsWith("input/")); const outputFiles = session.files.filter(record => record.path.startsWith("output/"));
  const selectedFile = file ? session.files.find(record => record.path === file) : null;
  return <Box component="aside" className="factory-inspector" aria-label={t("nextSteps")} sx={{ height: "100%", minWidth: 0, display: "flex", flexDirection: "column", bgcolor: "var(--hatch-ui-surface-sidebar)" }}><Toolbar className="factory-pane-header" variant="dense" sx={{ minHeight: 56, borderBottom: 1, borderColor: "divider" }}><AutoAwesome fontSize="small" sx={{ mr: 1 }} /><Box sx={{ flex: 1 }} />{entry && <AgentState entry={entry} agentName={agentName} t={t} />}</Toolbar><Box className="factory-inspector-scroll" sx={{ overflow: "auto", flex: 1, minHeight: 0, p: 1.5 }}><Binding s={session} t={t} />{entry && <NextSteps entry={entry} todos={session.todos || []} onOpenAgent={onOpenAgent} onUseLatest={useLatest} busy={busy} agentName={agentName} t={t} />}<Paper variant="outlined" sx={{ mb: 1.5, overflow: "hidden" }}><Box sx={{ px: 1.5, py: 1, borderBottom: 1, borderColor: "divider", display: "flex", alignItems: "center", gap: 1 }}><FolderOpen fontSize="small" /><Typography variant="caption" fontWeight={750}>{t("files")}</Typography><Chip size="small" label={session.files.length} sx={{ ml: "auto" }} /><Button component="label" size="small" startIcon={<UploadFile />} disabled={running || busy}>{t("addFiles")}<input hidden type="file" multiple onChange={event => { upload([...event.target.files]); event.target.value = ""; }} /></Button></Box><Box sx={{ p: 1.5 }}><FileSection title={t("attachments")} records={inputFiles} onOpen={setFile} onDelete={path => perform(() => api(endpoint(root, id, "files"), { method: "DELETE", body: { path } }))} canDelete={!running} t={t} /><FileSection title={t("outputs")} records={outputFiles} onOpen={setFile} selectable selectedOutputs={selectedOutputs} setSelectedOutputs={setSelectedOutputs} t={t} />{outputFiles.length > 0 && <Paper variant="outlined" sx={{ mt: 1.5, p: 1.5 }}><Typography variant="caption" color="text.secondary">{t("sendOutputsTo")}</Typography><Stack direction="row" spacing={1} sx={{ mt: 1 }}><FormControl fullWidth size="small"><InputLabel>{t("destinationAgent")}</InputLabel><Select label={t("destinationAgent")} value={destinationRole} onChange={event => setDestinationRole(event.target.value)}><MenuItem value="">{t("chooseAgent")}</MenuItem>{destinations.map(candidate => <MenuItem key={candidate.role} value={candidate.role}>{agentName(candidate.role)}</MenuItem>)}</Select></FormControl><Button variant="outlined" disabled={!destinationRole || !selectedOutputs.length || busy} onClick={transferOutputs}>{t("sendFiles", selectedOutputs.length)}</Button></Stack>{handoffNotice ? <Alert severity="success" sx={{ mt: 1 }}>{handoffNotice}</Alert> : <Typography variant="caption" color="text.secondary" sx={{ display: "block", mt: 1 }}>{t("handoffHint")}</Typography>}</Paper>}</Box></Paper>{selectedFile && <FileViewer key={file} root={root} running={running} id={id} record={selectedFile} files={session.files} onOpenFile={setFile} onAddToChat={addToChat} onClose={() => setFile(null)} t={t} perform={perform} />}</Box></Box>;
}

function FileSection({ title, records, onOpen, onDelete, canDelete, selectable, selectedOutputs = [], setSelectedOutputs, t }) {
  return <Paper variant="outlined" sx={{ mb: 1.5, overflow: "hidden" }}><Box sx={{ px: 1.5, py: 1, borderBottom: 1, borderColor: "divider" }}><Typography variant="caption" fontWeight={750}>{title}</Typography></Box>{records.length ? <List dense disablePadding>{records.map(record => <ListItemButton key={record.path} onClick={() => onOpen(record.path)} sx={{ py: .65, px: 1.5 }}><ListItemIcon sx={{ minWidth: 28 }}>{selectable ? <input aria-label={t("selectFile", record.path)} type="checkbox" checked={selectedOutputs.includes(record.path)} onChange={event => setSelectedOutputs(paths => event.target.checked ? [...paths, record.path] : paths.filter(path => path !== record.path))} onClick={event => event.stopPropagation()} /> : <Description fontSize="small" color="action" />}</ListItemIcon><ListItemText primary={record.path.replace(/^(input|output)\//, "")} primaryTypographyProps={{ noWrap: true, fontSize: 12 }} />{canDelete && /^(input\/(?:manual|handoff))\//.test(record.path) && <IconButton size="small" aria-label={t("removeFile", record.path)} onClick={event => { event.stopPropagation(); onDelete(record.path); }}><DeleteOutlineOutlined fontSize="small" /></IconButton>}<ChevronRight fontSize="small" color="disabled" /></ListItemButton>)}</List> : <Typography variant="caption" color="text.secondary" sx={{ display: "block", px: 1.5, py: 2 }}>{t("noFiles")}</Typography>}</Paper>;
}

function FileViewer({ root, running, id, record, files, onOpenFile, onClose, onAddToChat, t, perform }) {
  const draftKey = `factory-file-draft:${id}:${record.path}`; const [savedDraft] = useState(() => { try { return JSON.parse(sessionStorage.getItem(draftKey) || "null"); } catch { return null; } }); const [file, setFile] = useState(savedDraft?.file || null); const [edit, setEdit] = useState(savedDraft?.edit || ""); const [copyName, setCopyName] = useState(savedDraft?.copyName || ""); const [readError, setReadError] = useState(""); const dirty = Boolean(file && file.content !== null && edit !== file.content);
  useEffect(() => { if (!file) return; if (dirty) sessionStorage.setItem(draftKey, JSON.stringify({ file, edit, copyName })); else sessionStorage.removeItem(draftKey); }, [draftKey, file, edit, copyName, dirty]); useEffect(() => { api(`${endpoint(root, id, "files")}?path=${encodeURIComponent(record.path)}`).then(value => { setReadError(""); if (!dirty) { setFile(value); setEdit(value.content || ""); } }).catch(e => setReadError(e.message)); }, [root, id, record.path]);
  const requiresCopyName = record.readonly || record.path.startsWith("input/"); const saveDisabled = running || !dirty || (requiresCopyName && !copyName.trim());
  const save = () => perform(async () => { const target = requiresCopyName ? `output/${copyName}` : record.path; if (!target.endsWith(".md") || target.includes("..")) throw new Error(t("markdownFilenameRequired")); const bytes = new TextEncoder().encode(edit); let binary = ""; for (let i = 0; i < bytes.length; i += 8192) binary += String.fromCharCode(...bytes.subarray(i, i + 8192)); await api(endpoint(root, id, "files"), { method: "POST", body: { path: target, base64: btoa(binary) } }); sessionStorage.removeItem(draftKey); setFile({ ...file, content: edit }); });
  return <Dialog open onClose={onClose} fullWidth maxWidth="md" scroll="paper" aria-labelledby={`factory-file-dialog-${id}`}><DialogTitle id={`factory-file-dialog-${id}`} sx={{ p: 0 }}><Toolbar variant="dense" sx={{ minHeight: 52 }}><Description fontSize="small" sx={{ mr: 1 }} /><Typography variant="body2" fontWeight={700} noWrap sx={{ flex: 1 }} title={record.path}>{record.path.split("/").at(-1)}</Typography><Tooltip title={t("addToChat")}><IconButton size="small" onClick={() => onAddToChat(record.path)}><Send fontSize="small" /></IconButton></Tooltip><Tooltip title={t("download")}><IconButton component="a" size="small" href={`${endpoint(root, id, "files")}?path=${encodeURIComponent(record.path)}&download=1`}><Download fontSize="small" /></IconButton></Tooltip></Toolbar></DialogTitle><DialogContent dividers sx={{ p: 0 }}>{!file ? <Box sx={{ p: 2 }}><Stack spacing={1} alignItems="center"><CircularProgress size={18} /><Typography variant="caption" color="text.secondary">{readError || t("loadingFile")}</Typography></Stack></Box> : <><Box sx={{ p: 2, maxHeight: 520, overflow: "auto" }}>{readError && <ErrorNotice error={readError} />}{file.content === null ? <Typography variant="body2">{t("downloadToView")}</Typography> : <Stack spacing={1.5}><TextField multiline minRows={16} fullWidth value={edit} onChange={event => setEdit(event.target.value)} aria-label={t("markdownEditor")} />{requiresCopyName && <TextField label={t("revisionFilename")} placeholder={t("revisionFilenamePlaceholder")} value={copyName} onChange={event => setCopyName(event.target.value)} />}</Stack>}</Box>{file.content !== null && <Stack direction="row" spacing={1} sx={{ px: 2, pb: 2 }}><Button size="small" variant="contained" disabled={saveDisabled} onClick={save}>{t("save")}</Button><Button size="small" variant="outlined" disabled={!dirty} onClick={() => { setEdit(file.content || ""); sessionStorage.removeItem(draftKey); }}>{t("discardEdits")}</Button></Stack>}</>}</DialogContent><DialogActions><Button onClick={onClose}>{t("close")}</Button></DialogActions></Dialog>;
}

function AgentState({ entry, agentName, t, compact = false }) { if (entry?.state === "complete") return null; const gaps = agentDependencyGaps(entry); let text = t(agentStateKey(entry)); if (entry?.state === "locked" && gaps.required.length) text = t("finishAgentsFirst", gaps.required.map(agentName).join(t("roleSeparator"))); else if (entry?.state === "locked" && gaps.alternatives.length) text = t("finishOneAgentFirst", gaps.alternatives.map(agentName).join(t("roleSeparator"))); return <Chip size="small" icon={entry?.state === "locked" ? <Lock /> : undefined} label={compact ? undefined : text} color={entry?.state === "failed" ? "error" : entry?.state === "running" ? "primary" : "default"} variant={entry?.state === "running" ? "filled" : "outlined"} sx={compact ? { width: 10, height: 10, "& .MuiChip-icon": { display: "none" }, "& .MuiChip-label": { display: "none" } } : undefined} />; }
function AgentStartWorkspace({ entry, onOpenAgent, agentName, t }) { return <Box sx={{ p: 5, maxWidth: 720 }}><Typography variant="h4">{agentName(entry?.role)}</Typography><Box sx={{ mt: 2, mb: 3 }}><AgentState entry={entry} agentName={agentName} t={t} /></Box><NextSteps entry={entry} todos={[]} onOpenAgent={onOpenAgent} agentName={agentName} t={t} />{entry?.state === "ready" || entry?.state === "failed" ? <Button variant="contained" startIcon={<PlayArrow />} onClick={() => onOpenAgent(entry.role)}>{t(entry.state === "failed" ? "tryAgain" : "startAgent")}</Button> : null}</Box>; }
function NextSteps({ entry, todos, onOpenAgent, onUseLatest, busy, agentName, t }) { const gaps = agentDependencyGaps(entry); const availability = entry?.availability; const updatedDependencies = availability?.updatedDependencies || []; const locked = entry?.state === "locked"; const updated = entry?.state === "update_available"; if (!locked && !updated && !todos.length) return null; return <Stack spacing={1} sx={{ mb: 1.5 }}>{locked && <Alert severity="warning" variant="outlined"><Typography variant="caption" display="block" fontWeight={700}>{t("beforeStarting")}</Typography><Typography variant="caption">{t("completeUpstreamWork")}</Typography>{[...gaps.required, ...gaps.alternatives].map(role => <Button key={role} size="small" onClick={() => onOpenAgent(role)} endIcon={<ArrowForward />}>{agentName(role)}</Button>)}</Alert>}{updated && <Alert severity="info" action={<Button size="small" disabled={busy} onClick={onUseLatest}>{t("improveWithLatest")}</Button>}>{updatedDependencies.length ? updatedDependencies.map(agentName).join(t("roleSeparator")) : t("newWorkAvailable")}</Alert>}{todos.length > 0 && <Paper variant="outlined" sx={{ p: 1.25 }}><Stack direction="row" justifyContent="space-between"><Typography variant="caption" fontWeight={750}>{t("todo")}</Typography><Typography variant="caption" color="text.secondary">{todos.filter(todo => todo.status === "completed").length}/{todos.length}</Typography></Stack><Box className="factory-todo-list" sx={{ maxHeight: 220, overflowY: "auto", pr: 0.5 }}><Stack spacing={0.75}>{todos.map((todo, index) => <Box key={`${todo.title}-${index}`} className="factory-todo-row"><Typography component="span" variant="caption" className="factory-todo-marker" aria-hidden="true">{todo.status === "completed" ? "✓" : "○"}</Typography><Typography component="span" variant="caption" className="factory-todo-title" sx={{ color: todo.status === "completed" ? "text.secondary" : "text.primary", textDecoration: todo.status === "completed" ? "line-through" : "none" }}>{todo.title}</Typography></Box>)}</Stack></Box></Paper>}</Stack>; }
const toolActionKey = name => { const value = String(name || "").toLowerCase(); if (value.includes("update_todo")) return "toolActionUpdateTodo"; if (value.includes("corpus_upload")) return "toolActionCorpusUpload"; if (value.includes("evaluate")) return "toolActionEvaluate"; if (value.includes("search")) return "toolActionSearch"; if (value.includes("write")) return "toolActionWrite"; if (value.includes("read")) return "toolActionRead"; if (value.includes("list")) return "toolActionList"; return "toolActionUnknown"; };
const toolWorkKey = items => { const names = items.map(item => item.call?.name || item.result?.toolName || "").join(" ").toLowerCase(); if (names.includes("corpus_upload")) return "toolWorkPublish"; if (names.includes("list") || names.includes("read") || names.includes("search")) return "toolWorkGather"; if (names.includes("write") || names.includes("update_todo")) return "toolWorkBuild"; return "toolWorkMethod"; };
function ToolGroup({ items, running, t }) { const pending = items.some(item => !item.result); const failed = items.some(item => item.result?.isError); const status = pending ? t(running ? "toolCalling" : "toolMissing") : failed ? t("toolFailed") : ""; return <Accordion disableGutters variant="outlined" sx={{ mb: 1, "&:before": { display: "none" } }}><AccordionSummary expandIcon={<ExpandMore />}><Stack spacing={0.25}><Typography variant="body2" fontWeight={700}>{t(toolWorkKey(items))}</Typography><Typography variant="caption" color="text.secondary">{t("toolActionsCompleted", items.length)}{status ? ` · ${status}` : ""}</Typography></Stack></AccordionSummary><AccordionDetails sx={{ pt: 0 }}><Stack spacing={0.75}>{items.map(item => <ToolMessage key={item.key} call={item.call} result={item.result} running={running && item.isCurrentTurn} t={t} />)}</Stack></AccordionDetails></Accordion>; }
function ToolMessage({ call, result, running, t }) { const rawName = call?.name || result?.toolName || ""; const status = result?.isError ? t("toolFailed") : result ? "" : t(running ? "toolCalling" : "toolMissing"); const text = typeof result?.content === "string" ? result.content : result?.content?.filter(item => item.type === "text").map(item => item.text).join("\n"); return <Accordion disableGutters variant="outlined" sx={{ "&:before": { display: "none" } }}><AccordionSummary expandIcon={<ExpandMore />}><Stack spacing={0.25}><Typography variant="body2">{t(toolActionKey(rawName))}</Typography>{status && <Typography variant="caption" color="text.secondary">{status}</Typography>}</Stack></AccordionSummary><AccordionDetails sx={{ pt: 0 }}><Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 1 }}>{t("toolTechnicalDetails")} · {rawName}</Typography>{call && <><Typography variant="caption" fontWeight={700}>{t("toolArguments")}</Typography><Typography component="pre" variant="caption" sx={{ whiteSpace: "pre-wrap", display: "block" }}>{JSON.stringify(call.arguments, null, 2)}</Typography></>}{result && <><Typography variant="caption" fontWeight={700}>{t("toolResult")}</Typography><Typography component="pre" variant="caption" sx={{ whiteSpace: "pre-wrap", display: "block" }}>{text || ""}</Typography></>}</AccordionDetails></Accordion>; }
function Message({ message, files, onOpenFile, speaking, t }) { if (!message) return null; const text = typeof message.content === "string" ? message.content : message.content?.filter(item => item.type === "text").map(item => item.text).join("\n"); if (!text) return null; const user = message.role === "user"; return <Box component="article" className={`factory-message factory-message--${user ? "user" : "assistant"}`} sx={{ mb: 2.5, display: "flex", justifyContent: user ? "flex-end" : "flex-start" }}><Box className={user ? "factory-message-bubble" : "factory-message-content"}>{message.role === "assistant" ? <SpokenReply text={text} speaking={speaking} files={files} onOpenFile={onOpenFile} t={t} /> : <Markdown files={files} onOpenFile={onOpenFile} t={t}>{text}</Markdown>}</Box></Box>; }
function SpokenReply({ text, speaking, files, onOpenFile, t }) { const display = voiceText(text); const needle = voiceText(speaking?.text || ""); const index = needle ? display.indexOf(needle) : -1; if (index < 0) return <Markdown files={files} onOpenFile={onOpenFile} t={t}>{text}</Markdown>; return <Typography className="factory-markdown">{display.slice(0, index)}<mark>{display.slice(index, index + needle.length)}</mark>{display.slice(index + needle.length)}</Typography>; }
function voiceText(text) { return String(text).replace(/```[\s\S]*?```/g, " ").replace(/`[^`]*`/g, " ").replace(/!\[[^\]]*\]\([^)]*\)/g, " ").replace(/\[([^\]]+)\]\([^)]*\)/g, "$1").replace(/^\s*#{1,6}\s+/gm, "").replace(/^\s*(?:[-*+] |\d+\. )/gm, "").replace(/[*_~]/g, "").replace(/\s+/g, " ").trim(); }
function Binding({ s, t }) { return s.role === "generation" ? <Alert severity={s.corpus ? "success" : "info"} variant="outlined" sx={{ mb: 1 }}>{t(s.corpus ? "agentPublished" : "agentUnpublished")}</Alert> : null; }
function PromptDialog({ prompt, onClose, t }) { return <Dialog open={Boolean(prompt)} onClose={onClose} maxWidth="md" fullWidth><DialogTitle>{t("systemPrompt")}</DialogTitle><DialogContent><Typography component="pre" sx={{ whiteSpace: "pre-wrap", fontFamily: "monospace" }}>{prompt}</Typography></DialogContent><DialogActions><Button onClick={onClose}>{t("close")}</Button></DialogActions></Dialog>; }
function VoiceControls({ root, id, enabled, handler, onSpeaking, onError, t }) { const [active, setActive] = useState(false); const [partial, setPartial] = useState(""); const resources = useRef(null); const audioQueue = useRef(Promise.resolve()); const player = useRef(null); if (!player.current) player.current = new FactoryVoicePlayer(onSpeaking, onError); useEffect(() => { handler.current = event => { if (["voice.interrupt", "voice.user_speaking", "voice.transcript.final"].includes(event.type)) player.current.stop(); if (event.type === "voice.transcript.partial") setPartial(event.text || ""); if (event.type === "voice.transcript.final") setPartial(""); if (event.type === "voice.audio.start") player.current.start(event); if (event.type === "voice.speech.start") player.current.registerSpeech(event); if (event.type === "voice.speech.end") player.current.endSpeech(event); if (event.type === "voice.audio.chunk") player.current.chunk(event); if (event.type === "voice.audio.end") player.current.end(); if (event.type === "voice.error") onError(event.message); }; return () => { handler.current = () => {}; player.current.stop(); }; }, [handler, onError, onSpeaking]); const stop = async () => { player.current.stop(); const current = resources.current; resources.current = null; current?.processor.disconnect(); current?.source.disconnect(); current?.silence.disconnect(); current?.stream.getTracks().forEach(track => track.stop()); void current?.context.close(); setActive(false); setPartial(""); await api(endpoint(root, id, "voice/stop"), { method: "POST", body: {} }).catch(error => onError(error.message)); }; const start = async () => { try { const stream = await navigator.mediaDevices.getUserMedia({ audio: { channelCount: 1, echoCancellation: true, noiseSuppression: true, autoGainControl: true } }); const context = new AudioContext({ sampleRate: 16000 }); await context.resume(); const source = context.createMediaStreamSource(stream); const processor = context.createScriptProcessor(4096, 1, 1); const silence = context.createGain(); silence.gain.value = 0; processor.onaudioprocess = event => { const input = event.inputBuffer.getChannelData(0); const bytes = new Uint8Array(input.length * 2); const view = new DataView(bytes.buffer); for (let i = 0; i < input.length; i++) { const value = Math.max(-1, Math.min(1, input[i])); view.setInt16(i * 2, value < 0 ? value * 0x8000 : value * 0x7fff, true); } let binary = ""; for (let i = 0; i < bytes.length; i += 8192) binary += String.fromCharCode(...bytes.subarray(i, i + 8192)); audioQueue.current = audioQueue.current.then(() => api(endpoint(root, id, "voice/audio"), { method: "POST", body: { base64: btoa(binary) } })).catch(error => onError(error.message)); }; resources.current = { stream, context, source, processor, silence }; await api(endpoint(root, id, "voice/start"), { method: "POST", body: {} }); source.connect(processor); processor.connect(silence); silence.connect(context.destination); setActive(true); } catch (error) { await stop(); onError(error.message); } }; useEffect(() => () => { void stop(); }, [id]); return <Stack className="factory-voice-controls" direction="row" spacing={1} alignItems="center" sx={{ px: 1.5, pb: 1 }}><Button size="small" variant={active ? "outlined" : "contained"} disabled={!enabled} onClick={active ? stop : start}>{t(active ? "stopVoice" : "startVoice")}</Button><Typography variant="caption" color="text.secondary">{partial || (enabled ? (active ? t("listening") : "") : t("voiceUnavailable"))}</Typography></Stack>; }
function factoryError(error, t, agentName) { if (error?.code === "agent_dependencies_not_ready") { const required = error.details?.missingRequired || []; const alternatives = error.details?.normalCandidates || []; if (required.length) return t("finishAgentsFirst", required.map(agentName).join(t("roleSeparator"))); if (alternatives.length) return t("finishOneAgentFirst", alternatives.map(agentName).join(t("roleSeparator"))); return t("agentNeedsPreparation"); } if (error?.code === "agent_definitions_unavailable" || error?.code === "agent_definitions_invalid") return t("agentSetupUnavailable"); return error?.message || t("unknownFactoryError"); }
